actor EventLog {
    private var parts: [String] = []
    func add(_ s: String) { parts.append(s) }
    func text() -> String { parts.joined() }
}

func awaitInTask(_ log: EventLog) async {
    defer {
        Task {
            try? await Task.sleep(for: .milliseconds(15))
            await log.add(token3)
        }
    }
    await log.add(token1)
}

func directAwait(_ log: EventLog) async {
    defer {
        try? await Task.sleep(for: .milliseconds(15))
        await log.add(token3)
    }
    await log.add(token1)
}

